def stable_hash(ch):
    h = 0
    for c in ch:
        h = (h * 31 + ord(c)) & 0xFFFFFFFF
    return h

def simhash(text, dim=64):
    v = [0] * dim
    for ch in text:
        h = stable_hash(ch)
        for i in range(dim):
            if (h >> i) & 1:
                v[i] += 1
            else:
                v[i] -= 1
    return "".join("1" if x > 0 else "0" for x in v)

def hamming(a, b):
    return sum(1 for x, y in zip(a, b) if x != y)

docs = ["机器学习很有趣", "机器学习真有趣", "今天天气很好"]
hs = [simhash(d) for d in docs]
print("哈希位数:", len(hs[0]))
dups = []
for i in range(1, len(docs)):
    if hamming(hs[i], hs[0]) <= 3:
        dups.append(i)
print("与首文档相似(<=3位)的索引:", dups)
